import{_ as t,c as a,a2 as e,o}from"./chunks/framework.CqbvlPrP.js";const h=JSON.parse('{"title":"缠论的终极秘密","description":"","frontmatter":{},"headers":[],"relativePath":"stock/chan/缠论理解.md","filePath":"stock/chan/缠论理解.md"}'),r={name:"stock/chan/缠论理解.md"};function n(s,p,c,i,d,l){return o(),a("div",null,p[0]||(p[0]=[e('<h1 id="缠论的终极秘密" tabindex="-1">缠论的终极秘密 <a class="header-anchor" href="#缠论的终极秘密" aria-label="Permalink to &quot;缠论的终极秘密&quot;">​</a></h1><p>在你操作级别的当下</p><p><strong>当下走势，不是在构建一个中枢,就是在离开中枢的路上</strong> (震荡 单边)</p><p>以这种思维看待走势</p><p>一切都变得清晰、明了</p><p>但这个简单的秘密</p><p>里面藏着缠论最最基础的理论</p><p>第一：中枢的构造</p><p>第二：级别的生长</p><p>一、中枢的构造：</p><p>在你理解了缠师所说的中枢后</p><p>你就会明白为什么缠师号称</p><p>缠论是《市场哲学的数学原理》</p><p>二、当你明白了级别的生长</p><p>就会明白缠师所说的自相似性 、自同构性 、可预测性</p><p>线段不过是将笔当成K线的再一次笔的划分</p><p>笔已经足够好用，故线段用处不大</p><p>这样，一个两级联立的双重观察、相互印证就产生了</p><p>（实战中可能会用到三级联立）</p><p>本级别的中枢构造</p><p>要次级别走势来保证，其数学性划分的成立</p><p>并从图形上证明其存在</p><p>而中枢的离开</p><p>是必然是次级别或次次级别的走势</p><p>中枢完成必离开，</p><p>无非是向上或是向下离开</p><p>缠论的确定性是次级别或次次级别的离开</p><p>（这个离开级别，决定了力度（涨跌速度、图形斜率））</p><p>就必然包涵其中</p><p>这时，中枢的构造和离开段的完全分类</p><p>就有了执行（实战）的条件和标准</p><p>完成分类不是什么上下盘的分类，</p><p>而是中枢的构造段和离开段的分类</p><p>是构造中枢或离开中枢的走势类型的分类</p><p>并且当下就应该清楚的知道，当下是什么级别的中枢</p><p>是该中枢的第几段</p><p>中枢完成后，如果离开，离开段最大是什么级别</p><p>可能性就那么几种</p><p>注意这里是两个级别的相互嵌套</p><p>（绝非递规出中枢）</p><p>使用同一个理论《缠论》</p><p>为何用缠论读大盘如掌上观纹</p><p>因为指数的合力更清晰、更难以操控</p><p>总结：</p><p>在你操作的级别中，从中枢构造或离开的角度看走势</p><p>（本次两个级别）</p><p>以中枢构造或离开的角度完全分类走势</p><p>（中枢构造两个级别，中枢离开可能会是次级别或次次级别三个级别）</p><p>加上级别这个转换器（用于中枢构造）</p><p>缠论就是各级别趋势、盘整加中枢的三个零件组合</p><p>而中枢又是次级别趋势、盘整加中枢的三个零件组合</p><p>这种分类并不难，不是当下的所谓上下盘的分类</p><p>而是有着可预测性的分类标准</p><p>呵呵，看完这些，</p><p>您迷糊了吗？缠成残废了吗？</p><p>这些您想通了吗？</p><p>这就是本馋理解的缠论的终极秘密！</p><p>与各位分享！水平有限，可能表达不清</p>',58)]))}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
